TLM.f("Sancti/11-23cc",{"officium":"S. Felicitatis Martyris","rule":["vide C7;"],"ruleInherited":["Psalmi Dominica","Antiphonas horas"],"fallback":"Commune/C7","sections":{"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, beátæ Felicitátis Martyris tuæ sollémnia recenséntes, méritis ipsíus protegámur et précibus."},{"k":"macro","name":"Per Dominum"}],"Secreta":[{"k":"text","la":"Vota pópuli tui, Dómine, propitiátus inténde: et, cujus nos tríbuis sollémnia celebráre, fac gaudére suffrágiis."},{"k":"macro","name":"Per Dominum"}],"Postcommunio":[{"k":"text","la":"Súpplices te rogámus, omnípotens Deus: ut, intercedéntibus Sanctis tuis, et tua in nobis dona multíplices, et témpora nostra dispónas."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ab609018c8e6d809":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da slaveći svetkovinu blažene Felicite mučenice tvoje budemo zaštićeni njezinim zaslugama i molitvama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"41a5135de0f8f352":{"t":"Umilostivljen pogledaj, Gospodine, darove svoga naroda i daj da se radujemo pomoći onih kojih nam svetkovinu dopuštaš slaviti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"25070ec1b7a1bac8":{"t":"<i>Pomolimo se</i>.\nPonizno te molimo, svemogući Bože, da po zagovoru tvojih svetih umnožiš u nama svoje darove i bdiješ nad našim životom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
